static void screen_record_player_timer_event_cb(struct _lv_timer_t *timer)
{
    lv_obj_t *      ui_Screen;
    ui_screen_record_play_obj_t * p_screen_param;

    ui_Screen           = timer->user_data;
    p_screen_param      = (ui_screen_record_play_obj_t *) lv_obj_get_user_data(ui_Screen);


    screen_record_player_time_update(p_screen_param);


}


void screen_record_player_timer_start(lv_obj_t * ui_Screen)
{
    ui_screen_record_play_obj_t * p_screen_param;

    p_screen_param      = (ui_screen_record_play_obj_t *) lv_obj_get_user_data(ui_Screen);


    if (p_screen_param->handle_timer == NULL) {
        p_screen_param->handle_timer = lv_timer_create(screen_record_player_timer_event_cb,200,ui_Screen);
        }

}






